def normalize_invoice_documents(apps, schema_editor):
    """Map pre-Checkout lifecycle values before enforcing the issued-document invariant."""
    from django.db.models.functions import Coalesce

    Invoice = apps.get_model('billing', 'Invoice')
    Invoice.objects.filter(status__in=('draft', 'confirmed')).update(status='posted')
    Invoice.objects.filter(status='cancelled').update(status='voided')
    Invoice.objects.update(
        posted_at=Coalesce('confirmed_at', 'created_at'),
        posted_at_source=models.Case(
            models.When(
                confirmed_at__isnull=False,
                then=models.F('confirmed_at_source'),
            ),
            default=models.Value('fallback'),
            output_field=models.CharField(max_length=24),
        ),
    )


